/* Practical methodology resources. Illustrations are teaching examples, not project evidence. */
window.RESEARCH_GUIDES = [
{id:'interviews',title:'User interviews',category:'collection',kind:'method',summary:'Understand needs, workflows and the reasons people give for their actions.',phases:['plan','collect'],use:'Use interviews to explore recent experiences, pain points, mental models, workarounds and constraints. Speak to people who actually perform the relevant tasks.',limits:'An interview describes reported experience. It does not demonstrate task success, establish prevalence across a population, or prove what people will do in the future.',collect:[['Profile & task context','Role, relevant experience, situation and how often the task occurs.','Context'],['Recent workflow','A concrete recent example, process steps, tools and people involved.','Reported experience'],['Problems & workarounds','What happened, its consequence, and how the person coped.','Reported experience'],['Difficulty & satisfaction','Optional anchored 1–5 ratings, with the wording and reason for each answer.','Self-report'],['Time & impact','Reported time, impact of the problem, source and any uncertainty.','Self-report'],['Supporting material','Permissioned quotes, examples, source IDs and contrary examples.','Traceable evidence']],steps:[['Start with a research question','Write what you need to understand and how it could affect a decision. Turn it into neutral discussion topics rather than asking the research question verbatim.'],['Prepare a short, neutral guide','Introduce the purpose and consent arrangements, then ask about role, recent experience, workflow, difficulties and a closing reflection. Pilot the guide with a colleague.'],['Ask about real episodes','“Tell me about the last time…” usually gives more useful evidence than “Would you use…?”. Follow the participant’s sequence and probe for examples without suggesting an answer.'],['Capture before interpreting','Use participant codes and source references. Label reported claims, direct observations and your interpretations separately. Debrief soon after the session.']],analysis:[['Label meaningful moments','Code quotes and reported events against the research questions, while allowing unexpected themes to emerge. Keep the original source attached.'],['Compare contexts','Compare users, tasks and situations. A difficulty may apply to beginners but not experienced users; preserve that difference.'],['Test your explanation','Look for exceptions and contradictions before writing an insight. Link the resulting explanation to the decision, with its limits.']],pitfalls:['Treating a stakeholder or proxy interview as direct user evidence.','Counting mentions as population percentages.','Turning hypothetical enthusiasm into a demand forecast.','Adding a rating without defining the scale or what it measures.'],example:'Illustrative example: “Three interviewed beginners described asking colleagues for help when a requirement was unclear” is supportable if the notes trace those reports. “Most customers cannot onboard alone” requires different evidence.',template:'interview-protocol',activities:['protocol','run-sessions','qual-analysis'],related:['qualitative-analysis','sampling','evidence-confidence']},
{id:'observation',title:'Field observation',category:'collection',kind:'method',summary:'See what people do in their real context, including the work that a process diagram leaves out.',phases:['plan','collect'],use:'Use observation when interruptions, handoffs, tools, workarounds or environmental constraints shape the experience. Agree what can be observed and when questions may be asked.',limits:'Being observed can change behaviour. A short visit may miss rare events, other shifts or unusual cases. Observed time is meaningful only with its task and conditions.',collect:[['Participant & setting','Coded role, relevant experience, environment and observation period.','Context'],['Task & action sequence','Task goal and the steps actually taken, including backtracking.','Observed behaviour'],['Tools & dependencies','Systems, documents, people, handoffs and waiting points.','Observed behaviour'],['Friction & recovery','Errors, hesitation, interruptions, rework and workarounds.','Observed behaviour'],['Time & effort','Timed steps if observable; distinguish active work from waiting.','Observed measure'],['Comments & interpretation','Permissioned comments; separate observer interpretation and contextual limits.','Separated evidence']],steps:[['Scope the observation','Choose a task or workflow and the situations you need to see. Arrange access, consent, confidentiality and a safe way to capture notes.'],['Agree your role','Tell the participant whether you will silently observe or ask occasional questions. Avoid improving the workflow while you are trying to understand it.'],['Record the sequence','Capture actions, tools, transitions and friction in order. Note timestamps only when they help answer the question. Do not infer an emotion solely from a facial expression.'],['Clarify without rewriting events','After a suitable pause, ask what the participant was trying to achieve. Keep their explanation next to, but distinct from, the observed action.']],analysis:[['Map the actual workflow','Organise evidence by task step, tools, dependencies and consequences. Separate normal work from exceptional conditions.'],['Compare situations','Check which interruptions or failures recur across settings and which depend on a specific role or tool.'],['Explain the mechanism','Connect a friction point to its trigger, user impact and supporting observations. State what the visit did not cover.']],pitfalls:['Assuming the documented workflow is the observed workflow.','Helping the user before recording the problem.','Treating an unobserved event as proof that it never happens.','Mixing measured time with a participant’s estimated time.'],example:'Illustrative example: an approval task takes two minutes of active work and twenty minutes waiting for another team. Report those separately; an interface speed improvement may not address the main delay.',template:'observation-grid',activities:['protocol','run-sessions','organise-evidence'],related:['interviews','qualitative-analysis','evidence-confidence']},
{id:'workshops',title:'Workshops, co-design & ideation',category:'collection',kind:'method',summary:'Bring people together to interpret evidence, explore options and make tradeoffs explicit.',phases:['kickoff','plan','collect','share'],use:'Use a workshop when the purpose is shared understanding, exploration of possible solutions, or alignment on priorities. Start from research insights rather than treating the session itself as validation.',limits:'A workshop vote reflects the people in that room. Stakeholder agreement, ideas generated and dot votes are not proof of user need, market demand or solution effectiveness.',collect:[['People represented','Participant profiles, roles and whether actual users or proxies took part.','Context'],['Evidence inputs','Research insights, source references and how-might-we questions.','Research input'],['Ideas & concepts','Options generated and the assumptions behind them.','Generated material'],['Prioritisation','Voting method, criteria, results and any dissent.','Group judgement'],['Decision rationale','Selected concepts, why they were selected, risks and next tests.','Decision record']],steps:[['Define the session outcome','Choose whether the session should frame a problem, generate options or decide priorities. Invite the roles required for that outcome.'],['Make evidence visible','Present a concise set of traceable insights and limitations. Give people time to read before they argue for a preferred solution.'],['Separate divergence and convergence','Allow quiet individual thinking, then compare ideas against shared criteria. Capture minority views instead of forcing consensus.'],['Close with testable next steps','Record selected concepts, the rationale, remaining assumptions and who will gather the next evidence.']],analysis:[['Organise the outputs','Group ideas, rationale and votes without treating vote counts as research findings. Retain the participant mix and voting rules.'],['Trace to the evidence','Show which user need each concept addresses and which part remains an assumption.'],['Identify the next study','Use interviews, observation or testing to address uncertainty that discussion cannot resolve.']],pitfalls:['Calling an internally preferred concept “user validated”.','Losing minority opinions when reporting the winning option.','Counting ideas or votes as a product success measure.'],example:'Illustrative example: a team votes for a one-page form. The output is a prioritised concept and rationale. Whether users can complete that form still needs an appropriate evaluation.',template:'ideation-canvas',activities:['frame-problem','align-constraints','facilitate-decisions'],related:['interviews','usability','evidence-confidence']},
{id:'surveys',title:'Surveys & questionnaires',category:'collection',kind:'method',summary:'Gather consistent answers across respondents, with clear scales and a deliberate sample.',phases:['plan','collect','analyse'],use:'Use a survey to describe reported experiences, compare relevant groups, explore priorities or collect a consistent satisfaction or difficulty measure. First establish that respondents can understand and answer the questions.',limits:'A large response count does not fix a biased recruitment route. Survey answers measure what people report; they do not directly demonstrate behaviour or establish causality.',collect:[['Respondent profile','Relevant segment, experience and screening criteria.','Context'],['Use & frequency','Defined task, recall period and answer options.','Self-report'],['Satisfaction / difficulty','Exact wording, labelled scale, direction and missing-response rule.','Self-report measure'],['Time, usefulness & severity','Only measures relevant to the decision; distinguish estimates from observed data.','Self-report measure'],['Priorities & open comment','Ranking rules or choices plus optional explanations.','Reported preference'],['Sample & fieldwork','Recruitment route, period, invitations if known, responses and exclusions.','Coverage metadata']],steps:[['Map each question to a decision','Remove questions with no clear use. Define the population, recruitment route and how the results will be analysed before fieldwork.'],['Write clear answerable questions','Ask one thing at a time. Avoid leading wording, double questions, unclear time periods and answer options that omit common situations.'],['Pilot with relevant people','Check interpretation, flow, time, scale labels and whether “not applicable” is needed. Make the invitation and consent information clear.'],['Monitor coverage','Track relevant groups and obvious data-quality issues. Do not change a live question casually: record versions so incompatible answers are not pooled.']],analysis:[['Prepare the data','Work on a copy, record exclusions and inspect missing responses. Keep the denominator for each question or subgroup.'],['Describe distributions','Show counts and distributions alongside any summary. For a single ordinal rating, the distribution or median is often more informative than an unexplained average.'],['Compare carefully','Compare groups or time periods only when definitions and recruitment are sufficiently comparable. Consult an analyst when the decision depends on inference or a reliable change estimate.']],pitfalls:['Writing “80% of users” when the evidence is 8 of 10 convenience respondents.','Treating a 1–5 difficulty item as equivalent to a different instrument.','Interpreting preference as task success.','Ignoring nonresponse or missing segments.'],example:'Illustrative example: 8 of 10 respondents rated the process difficult. Report “8/10 respondents”, the recruitment route and the group represented. This alone does not estimate the proportion of all customers who struggle.',template:'survey-plan',activities:['research-plan','sampling','quant-analysis'],related:['quantitative-analysis','sampling','evidence-confidence']},
{id:'usability',title:'Usability & prototype testing',category:'collection',kind:'method',summary:'Check whether intended users can complete realistic tasks, and understand where they struggle.',phases:['plan','collect','analyse'],use:'Use usability testing when there is a product, prototype or concept with enough detail for the task you need to evaluate. Decide whether the aim is finding problems or measuring performance before defining the study.',limits:'A prototype test is evidence about the tested experience under its conditions. It is not a forecast of live adoption or business performance. A small formative study does not provide a precise population success rate.',collect:[['Scenario & task','Realistic goal, starting point, tested version and success criteria.','Study definition'],['Task outcome','Success, assisted / partial completion or failure, with rules agreed in advance.','Observed behaviour'],['Time, errors & help','Timing boundaries, error definitions, assistance and deviations.','Observed measure'],['Friction & blockers','What happened, where, source reference and impact on the task.','Qualitative observation'],['Post-task perception','Clearly labelled ease / difficulty scale, exact wording and rationale.','Self-report'],['Post-session measure','If used, retain the wording, scale and scoring of the chosen instrument, such as UMUX-Lite.','Instrument-specific measure']],steps:[['Write tasks and success criteria','Use a user goal, not navigation instructions that give away the answer. Define success, assistance, errors and timing boundaries before testing.'],['Pilot the material','Check prototype fidelity, links, data, access and task clarity. Ensure participants can attempt the task without technical obstacles unrelated to the question.'],['Observe without coaching','Invite participants to think aloud where appropriate. Use neutral prompts and record help when it is necessary; do not silently score assisted completion as independent success.'],['Debrief the experience','Ask about observed moments and ratings without defending the design. Capture contextual limitations and changes to the protocol.']],analysis:[['Summarise task evidence','Use counts of success, assistance and failure per task; keep the denominator. Analyse time only with its completion and assistance conditions.'],['Connect metrics to behaviour','Use observations to explain a failure or long duration. Group related breakdowns while retaining the task and affected user context.'],['Prioritise consequences','Distinguish a blocker from a minor friction point. Tie recommendations to evidence, impact and confidence, then plan a focused retest.']],pitfalls:['Testing a prototype whose missing functionality prevents a fair attempt.','Changing success criteria after seeing the results.','Equating preference, ease ratings and task success.','Relabelling UMUX-Lite scores as SUS without an explicitly justified, documented scoring approach.'],example:'Illustrative example: on one task, 5/8 participants complete it independently, 2/8 need help and 1/8 fails. Keep those categories visible. Do not report 7/8 unqualified “successes”.',template:'usability-protocol',activities:['protocol','run-sessions','quant-analysis'],related:['quantitative-analysis','sampling','evidence-confidence']},
{id:'existing-evidence',title:'Analytics & existing evidence',category:'collection',kind:'method',summary:'Use what already exists to understand behaviour, establish a reference point and focus new research.',phases:['readiness','plan','collect','analyse'],use:'Review analytics, earlier studies, support records, documentation and relevant external research before starting new collection. This is especially useful when user access is limited.',limits:'Existing material was collected for another purpose and may cover a different population or period. Analytics can reveal a pattern without explaining its cause. External findings need contextual checks before reuse.',collect:[['Source & provenance','Link, owner, collection method, date and purpose.','Source metadata'],['Metric definition','Event / unit, numerator, denominator, population and period.','Measurement definition'],['Usage & process','Frequency, active users, funnel steps, completion time or adoption when available.','Behavioural data'],['Support & quality','Incidents, recurring complaints, error / rework patterns and historical satisfaction.','Mixed evidence'],['Relevance & limitations','Coverage, reliability, missing context and what can be reused.','Assessment']],steps:[['Start with the evidence question','Specify which uncertainty the source could address. Inventory internal knowledge before searching widely.'],['Check definitions and coverage','Ask how the data was produced, what is missing, and whether the population and period fit this decision. Consult the data owner where definitions are unclear.'],['Extract traceable findings','Keep a link to each source and record the exact measure or observation. Label external analogies and stakeholder claims appropriately.'],['Define the remaining gap','State what is supported, what remains an assumption and whether new user research is needed. Do not duplicate a question that existing evidence already answers adequately.']],analysis:[['Harmonise before comparing','Do not combine conflicting event definitions, time windows or populations as though they were one dataset.'],['Look for decision-relevant patterns','Inspect funnels and segments, changes over time and recurrent issues. Distinguish correlation from a causal explanation.'],['Combine with direct evidence','Use interviews or observations to investigate possible causes when available. Keep source independence and limitations visible.']],pitfalls:['Treating drop-off as proof of why people left.','Counting repeated reports from the same source as independent confirmation.','Copying a market statistic into a product forecast without checking fit.'],example:'Illustrative example: analytics show exits at an identity step, while support records describe unclear document rules. That suggests a question to investigate; it does not yet prove the rules caused every exit.',template:'evidence-extraction',activities:['review-evidence','organise-evidence','quant-analysis'],related:['evidence-confidence','quantitative-analysis','interviews']},
{id:'expert-review',title:'Expert & heuristic review',category:'collection',kind:'method',summary:'Identify likely usability risks when you need a focused review or cannot yet involve users.',phases:['readiness','plan','collect'],use:'Use a structured expert review to inspect an experience against explicit criteria, identify likely problems, and plan what to check with users. Make the reviewer’s expertise and coverage clear.',limits:'Expert judgement is not user validation. It cannot establish how often a problem occurs, how users actually behave, or whether a solution meets real needs.',collect:[['Scope & criteria','Flows, version, relevant principles and exclusions.','Review definition'],['Reviewer & rationale','Relevant expertise and reasoning for each judgement.','Expert judgement'],['Issue record','Location, screenshot / source, affected task and likely consequence.','Review finding'],['Priority & next validation','Severity rationale, uncertainty and the user check needed.','Assessment']],steps:[['Set scope and criteria','Choose the flows and review principles. Use realistic task goals and note what the reviewer cannot inspect.'],['Inspect systematically','Walk through each task and capture the exact location and reasoning for each issue. Avoid relying on aesthetic preference alone.'],['Calibrate findings','If several reviewers participate, compare independent findings and discuss differences before consolidating.'],['Define follow-up','Prioritise plausible risks, distinguish evidence from judgement, and assign a future user check where a decision depends on it.']],analysis:[['Group by task and consequence','Combine duplicate review findings without losing the rationale.'],['State the limit','Report likely risks, not measured user outcomes. Keep untested assumptions visible.']],pitfalls:['Using “validated” to describe an expert’s agreement.','Presenting a subjective severity rating as an observed frequency.'],example:'Illustrative example: a reviewer finds ambiguous error recovery in a payment flow. Record a plausible task risk and a plan to observe recovery with relevant users, rather than claiming users definitely fail.',template:'expert-review-sheet',activities:['assess-readiness','align-constraints','review-evidence'],related:['usability','evidence-confidence']},
{id:'qualitative-analysis',title:'From raw evidence to qualitative insights',category:'analysis',kind:'guide',summary:'Code what happened, challenge patterns and write insights that remain traceable.',phases:['analyse'],use:'Use this workflow for notes, transcripts, field observations, open comments and session evidence. Begin with organised source material and the research questions, not a blank affinity wall.',limits:'Qualitative recurrence is a signal about the studied situations. It is not a prevalence estimate. An insight should explain an experience, not simply rename a topic or repeat a collection of quotes.',collect:[['Source reference','Participant code, method, date, relevant segment and source link.','Evidence index'],['Evidence excerpt','Quote or observation, with the task and context.','Raw material'],['Code & definition','Short label, meaning and inclusion / exclusion examples.','Analysis decision'],['Pattern & exceptions','Related observations, contexts and contradictory cases.','Interpretation'],['Insight & confidence','Explanation, affected users, impact, uncertainty and decision informed.','Synthesis']],steps:[['Prepare and calibrate','Keep raw material intact. Agree a practical coding approach and review one session together if more than one analyst is involved. Begin with research topics, but allow unexpected labels.'],['Code meaningful moments','Label what people say, do, avoid, misunderstand or find useful. Keep the excerpt and source attached; do not jump straight to a recommendation.'],['Check coverage before clustering','Ask whether the right users, tasks and situations were represented. An unanswered decision-critical question needs targeted follow-up; a minor gap can be recorded as a limitation.'],['Build and challenge patterns','Group related evidence, give the group a provisional descriptive name, and search for exceptions. Compare contexts rather than flattening different experiences into one theme.'],['Write a bounded insight','Explain what happens, for whom, in which situation, why it matters and what supports the explanation. Record confidence and uncertainty before discussing a solution.']],analysis:[['Separate the levels','Keep observation → code → pattern → insight → recommendation distinguishable, even if your working board is informal.'],['Review the chain','Ask a colleague to trace a claim back to its sources and look for overstatement or neglected contrary evidence.'],['Decide whether to collect more','Return to the missing group, task or question only if the gap could change the decision. Do not restart the whole study by default.']],pitfalls:['Creating an elaborate taxonomy that prevents comparison.','Treating the loudest or most memorable quote as the main finding.','Discarding positive experiences and exceptions.','Calling “search is confusing” an explanation without investigating the mechanism.'],example:'Illustrative example: several beginners say they ask a colleague when they do not know an item’s exact name; observations show repeated search reformulation. A candidate insight is that exact-name search provides little support for unfamiliar terminology. Preserve the evidence, scope and exceptions before proposing a fix.',template:'qualitative-evidence-chain',activities:['qual-analysis','combine-insights'],related:['evidence-confidence','sampling','quantitative-analysis']},
{id:'quantitative-analysis',title:'Prepare and interpret quantitative evidence',category:'analysis',kind:'guide',summary:'Understand what the numbers represent before comparing them or drawing a conclusion.',phases:['plan','analyse'],use:'Use this workflow for survey answers, task outcomes, measured durations, product analytics and other numerical evidence. Reopen the research question, metric definitions and sampling approach first.',limits:'Descriptive differences do not automatically establish a reliable effect. Statistical analysis cannot repair an unsuitable sample or an inconsistent measure. Important comparisons may need an analyst or research specialist.',collect:[['Measure & unit','Definition, scale, event or task, version and time period.','Measurement metadata'],['Coverage & denominator','Respondents / users / attempts represented, relevant segments and missingness.','Sample metadata'],['Cleaning log','Duplicates, tests, exclusions, transformations and the reason for each change.','Audit trail'],['Result & comparison','Counts, distribution, appropriate summary and comparable reference point.','Descriptive result'],['Interpretation & limits','Impact, uncertainty, alternative explanations and decision supported.','Qualified finding']],steps:[['Protect and prepare the source','Keep original data unchanged and analyse a copy. Remove only documented invalid entries, preserve meaningful missing values, and record changes so someone can repeat the preparation.'],['Check who and what is represented','Compare the data with the intended users, tasks and period. Inspect subgroup coverage; a large total may hide a missing or underrepresented group.'],['Describe the relevant result','Show counts behind percentages. Inspect distributions and unusual values before choosing summaries. Distinguish independent task success from assisted completion, and observed time from reported time.'],['Make fair comparisons','Check that definitions, instruments, task conditions and recruitment are comparable. Do not casually pool different scale versions or measurement periods.'],['Match the claim to the design','Report what the study can support. If a decision needs a precise population estimate, reliable change comparison or causal effect, involve a specialist and document the required design and uncertainty.']],analysis:[['Connect numbers and context','Interpret a low ease score with task observations or interviews where available; do not invent a cause from a chart.'],['State strengths as well as problems','Preserve successful experiences and check whether a small difference is meaningful for the decision.'],['Write a qualified finding','Include the measure, result, denominator, affected group, comparison, limitation and implication. Keep the recommendation separate.']],pitfalls:['Reporting 60% without saying whether it means 3/5 or 300/500.','Confusing a small numerical difference with evidence of improvement.','Claiming causality from an observational comparison.','Scoring one usability instrument and labelling it as another.'],example:'Illustrative example: 3/5 participants and 300/500 participants both equal 60%, but the studies support very different precision claims. Neither result is representative merely because a percentage was calculated.',template:'quantitative-analysis-sheet',activities:['quant-analysis','combine-insights'],related:['sampling','evidence-confidence','usability']},
{id:'evidence-confidence',title:'Combine evidence and judge what is enough',category:'analysis',kind:'guide',summary:'Make confidence and remaining uncertainty visible in relation to the decision.',phases:['analyse','share'],use:'Use this guide when combining qualitative and quantitative results, handling contradictory sources, or deciding whether to collect more evidence before moving forward.',limits:'There is no universal number of interviews, survey responses or repeated mentions that makes every decision safe. Confidence labels are a reasoned assessment, not a calculated probability.',collect:[['Decision & potential impact','The choice the evidence must inform and the consequence of being wrong.','Decision context'],['Claim & support','What the claim says, relevant evidence and source independence.','Evidence chain'],['Contradictions & coverage','Who disagrees, which situations differ, and what is missing.','Challenge record'],['Confidence rationale','Why the claim is more or less credible, and its applicable scope.','Reasoned judgement'],['Next step','Proceed, narrow the claim, collect targeted evidence or escalate.','Decision record']],steps:[['Organise by the question','Bring methods together around the research questions and project choices. Avoid telling three separate method reports that the team must reconcile itself.'],['Inspect agreement and disagreement','Distinguish independent corroboration from several summaries of the same source. Where evidence differs, inspect user segments, definitions, periods and collection conditions.'],['Assess the remaining risk','Ask whether a gap concerns a key user group, core task, meaningful alternative or major risk. Record other uncertainties as limitations rather than demanding perfect knowledge.'],['Choose a proportionate response','Collect the smallest missing piece that could change the decision. If access is blocked, narrow the claim and make the limitation explicit to the decision owner.']],analysis:[['Write one combined insight','State the user situation, evidence from each applicable source, agreement / conflict, impact and scope. A study does not need every evidence type to be useful.'],['Preserve uncertainty','Record what is unknown, why it matters, who accepts the residual risk and whether a follow-up is needed.']],pitfalls:['Averaging contradictory stories into an apparently tidy consensus.','Treating many copies of one source as triangulation.','Using a high-confidence label without a rationale.','Continuing research indefinitely because some uncertainty remains.'],example:'Illustrative example: experienced users report no issue, while beginners struggle in tests. The contradiction may describe a segment difference. Refine the insight and test that explanation before calling either source wrong.',template:'insight-confidence-record',activities:['combine-insights','resolve-blockers','prepare-story'],related:['qualitative-analysis','quantitative-analysis','sampling']},
{id:'sampling',title:'Sampling, recruitment & evidence coverage',category:'planning',kind:'guide',summary:'Match participant coverage to the question and the claim you want to make.',phases:['plan','collect','analyse'],use:'Plan for relevant user groups, tasks, contexts and important differences. Decide whether the aim is exploring experiences, identifying usability problems, or making a population-level numerical claim.',limits:'A convenient sample can be useful for learning, but it has limits. Proxies and champions do not automatically represent actual users. A target sample size is not a guarantee of coverage or quality.',collect:[['Population & segments','Who the study concerns and important differences in role, experience or situation.','Study definition'],['Inclusion & recruitment','Screening, recruitment route, who may be excluded and why.','Sampling plan'],['Coverage target','Required contexts, task coverage and rationale for the approach.','Planning decision'],['Achieved coverage','Who participated, who did not, and what this means for conclusions.','Evidence metadata']],steps:[['Define who matters','Start with real tasks and contexts. Include uncommon but decision-critical user groups when relevant, rather than only easy-to-reach volunteers.'],['Match design to the claim','Exploration needs relevant variation and sufficient depth. Numerical estimates need an appropriate sampling approach and precision plan; involve an analyst when those claims matter.'],['Recruit transparently','Document screening and access routes. Distinguish actual users, stakeholders and proxies in both planning and reporting.'],['Review during collection','Compare achieved participation with the plan. Fill decision-critical gaps deliberately and state remaining limits.']],analysis:[['Look beyond the total','A large group of one role can conceal an absent role. Compare the data with the audience the decision affects.'],['Decide on follow-up','Name the missing group, task or time period and the evidence needed. Avoid an unqualified request for “more participants”.']],pitfalls:['Choosing a universal participant count without reference to method or decision.','Claiming representativeness from sample size alone.','Substituting available stakeholders for users without saying so.'],example:'Illustrative example: ten interviews with managers do not cover a workflow performed by back-office users. The next useful step may be observing that missing workflow, not interviewing more managers.',template:'coverage-plan',activities:['sampling','recruit-schedule','organise-evidence'],related:['surveys','usability','evidence-confidence']},
{id:'research-routing',title:'Choose a realistic research approach',category:'planning',kind:'guide',summary:'Start with the decision, then select an evidence mix that fits your question and constraints.',phases:['readiness','kickoff','plan'],use:'Use this guide when choosing between exploration, evaluation, measurement and stakeholder alignment. Reuse relevant knowledge before deciding what new evidence to collect.',limits:'The exploration / evaluation distinction is a starting point, not a rule that exploration is always qualitative or evaluation always quantitative. The question determines the evidence and method.',collect:[['Decision & question','What must be decided and which uncertainty blocks it.','Research frame'],['Product & available material','New idea, testable concept / prototype or existing experience.','Project context'],['Access & constraints','User access, time, budget, skill and what can still change.','Feasibility'],['Planned mix & gaps','Primary user evidence, existing sources, methods and limitations.','Research plan']],steps:[['Name the intent','Explore needs and context; evaluate how an experience works; measure a defined outcome; or align people around evidence. A project may need more than one intent.'],['Reuse and choose the evidence','For exploration, interviews or observation often establish context; existing evidence provides a starting point. For evaluation, realistic tasks and appropriate user tests can be combined with contextual explanation.'],['Check feasibility','Confirm access and testable material. On a constrained project, identify the smallest decision research can influence and label indirect or expert evidence honestly.'],['Agree the contribution','Write questions, methods, coverage, measures, analysis, outputs and limits. For a broad or strategic project, seek a research review instead of applying a fixed method checklist blindly.']],analysis:[['Review the evidence mix','Check whether each method answers a distinct need and how the findings will come together. Not every study needs every method.'],['Revisit when conditions change','A newly available prototype, a missing segment or blocked access can change the next useful step. Keep the rationale visible.']],pitfalls:['Choosing a favourite method before defining the question.','Using a workshop vote to answer a user-behaviour question.','Promising validation when only indirect evidence is feasible.'],example:'Illustrative example: for a new workflow with unclear needs, start by understanding existing work. For an existing screen with a known completion problem, observe realistic tasks and collect defined task outcomes; interviews can help explain the context.',template:'research-approach',activities:['assess-readiness','research-plan','align-constraints'],related:['sampling','existing-evidence','evidence-confidence']}
];

