window.RESEARCH_DIFFICULTIES = [
{id:'stale-evidence',title:'I cannot tell whether earlier research still applies',phases:['readiness','plan','reuse'],level:'advice',why:'Reusable evidence needs a clear scope and a check against today’s question.',actions:['Check the original users, task, product version, period and collection conditions.','Record what has changed, reuse only the supported claims and plan a focused check for decision-critical gaps.'],avoid:'Do not carry an old finding into a new context without its source and limitations.',guide:'existing-evidence',activity:'archive'},
{id:'unclear-question',title:'The question or decision is unclear',phases:['kickoff','plan'],level:'advice',why:'A method cannot compensate for an unclear purpose.',actions:['Write the decision and the uncertainty that blocks it.','Turn broad topics into answerable questions and map each to possible evidence.'],avoid:'Do not start collecting data just because a method is available.',guide:'research-routing',activity:'frame-problem'},
{id:'fixed-solution',title:'The solution or scope is already fixed',phases:['readiness','kickoff','plan'],level:'warning',why:'Research may have limited influence on the project.',actions:['Distinguish non-negotiables from choices that can still change.','Agree a focused risk-reduction contribution, explicit limitations and an escalation owner.'],avoid:'Do not promise full validation when the team cannot act on contrary evidence.',guide:'research-routing',activity:'align-constraints'},
{id:'no-users',title:'I cannot reach the intended users',phases:['readiness','plan','collect'],level:'warning',why:'Indirect sources cannot establish actual user behaviour on their own.',actions:['Review existing evidence and consider a structured expert review.','Label proxies, stakeholders and experts accurately; plan direct user follow-up when possible.'],avoid:'Do not relabel proxy opinion as user validation.',guide:'expert-review',activity:'assess-readiness'},
{id:'limited-time',title:'Time or resources are very limited',phases:['plan','collect'],level:'advice',why:'A narrow, useful study is better than an unachievable broad plan.',actions:['Prioritise the uncertainty most likely to change the decision.','Reuse relevant evidence and agree a smaller study, its limits and the follow-up it leaves.'],avoid:'Do not remove analysis time or essential consent and recruitment preparation to fit more sessions.',guide:'research-routing',activity:'research-plan'},
{id:'leading-questions',title:'Questions or tasks may be leading people',phases:['collect'],level:'advice',why:'Wording, coaching and task instructions can shape the answers or behaviour.',actions:['Pilot the guide with neutral wording and realistic tasks.','Ask for recent examples; log assistance separately during tests.'],avoid:'Do not ask participants to confirm a preferred design.',guide:'interviews',activity:'protocol'},
{id:'missing-segments',title:'Important users or situations are missing',phases:['plan','collect','analyse'],level:'warning',why:'A total participant count can conceal a critical coverage gap.',actions:['Identify the missing group, task or situation and whether it could change the decision.','Plan the smallest targeted follow-up; if blocked, explicitly narrow the conclusions.'],avoid:'Do not call the sample representative because it is large.',guide:'sampling',activity:'sampling'},
{id:'low-sample',title:'I have very little evidence',phases:['collect','analyse','share'],level:'warning',why:'Few observations can identify useful issues, but support limited claims.',actions:['Report counts, sources and context rather than population-wide percentages.','Check decision-critical gaps and collect targeted evidence if those gaps could change the choice.'],avoid:'Do not treat a fixed participant threshold as a guarantee of enough evidence.',guide:'evidence-confidence',activity:'organise-evidence'},
{id:'messy-data',title:'The evidence is messy or hard to compare',phases:['analyse'],level:'advice',why:'Inconsistent sources, units and coding make conclusions hard to verify.',actions:['Keep the original material and create an organised working copy with source IDs.','Agree coding definitions or metric definitions, document exclusions and separate incompatible measures.'],avoid:'Do not silently delete inconvenient responses or combine unlike scales.',guide:'quantitative-analysis',activity:'organise-evidence'},
{id:'conflicting-evidence',title:'Different sources tell different stories',phases:['analyse','share'],level:'advice',why:'Disagreement may describe different groups, tasks or collection conditions.',actions:['Compare scope, definitions, recruitment, time periods and source independence.','Look for a meaningful segment difference; record unresolved conflict and the follow-up needed.'],avoid:'Do not average away a contradiction or choose only the convenient source.',guide:'evidence-confidence',activity:'combine-insights'},
{id:'no-baseline',title:'There is no credible baseline or comparison',phases:['plan','analyse','share'],level:'warning',why:'Without a comparable reference, an improvement claim may be unsupported.',actions:['Define the measure and establish a baseline if feasible.','Otherwise describe the current result and set a future comparison plan with consistent conditions.'],avoid:'Do not turn a prototype result or an unrelated benchmark into a live-performance forecast.',guide:'quantitative-analysis',activity:'research-plan'},
{id:'unclear-impact',title:'I have themes, but not useful insights',phases:['analyse','share'],level:'advice',why:'A topic or quote collection does not yet explain the user experience.',actions:['Write what happens, to whom, in which context, and why it matters.','Attach supporting evidence, exceptions, confidence and the decision informed before recommending a solution.'],avoid:'Do not skip from a theme label straight to a feature request.',guide:'qualitative-analysis',activity:'qual-analysis'},
{id:'decision-blocked',title:'The team still cannot decide',phases:['kickoff','share'],level:'advice',why:'An evidence gap, a solution question and an alignment problem need different responses.',actions:['Name which kind of blocker prevents the decision.','Choose targeted research, solution exploration or stakeholder alignment, with an owner and review date.'],avoid:'Do not restart the whole study when a focused action will resolve the blocker.',guide:'evidence-confidence',activity:'resolve-blockers'}
];

/* Product problems are starting signals, not diagnoses of their causes. */
window.RESEARCH_PROBLEMS = [
{id:'adoption',label:'Low adoption or use',question:'What stops people from starting or using the product?',objective:'Understand what blocks adoption',measurement:'Establish adoption patterns and a baseline',methods:['existing-evidence','interviews','observation'],activities:['frame-problem','research-plan','sampling','protocol','run-sessions','quant-analysis','combine-insights'],focus:'Compare who uses the product, when use starts or stops, and what people expect or do instead.'},
{id:'satisfaction',label:'Low satisfaction',question:'What makes the experience disappointing or frustrating?',objective:'Explain dissatisfaction in its task context',measurement:'Measure satisfaction consistently and explain the ratings',methods:['surveys','interviews','usability'],activities:['frame-problem','research-plan','protocol','run-sessions','qual-analysis','quant-analysis','combine-insights'],focus:'Use consistent ratings where useful, then connect them to recent experiences and specific points of friction.'},
{id:'time',label:'Time lost or slow processes',question:'Where is time lost, and what causes the delay?',objective:'Find where time is lost in the workflow',measurement:'Separate active work, waiting and rework in the baseline',methods:['observation','existing-evidence','usability'],activities:['research-plan','protocol','run-sessions','organise-evidence','quant-analysis','combine-insights'],focus:'Observe the workflow and distinguish active work, waiting, handoffs and rework before attributing delay to the interface.'},
{id:'errors',label:'Errors or repeated rework',question:'When do errors happen, and how do people recover?',objective:'Identify the conditions behind errors and rework',measurement:'Define errors, recovery and their frequency consistently',methods:['usability','observation','existing-evidence'],activities:['research-plan','protocol','run-sessions','organise-evidence','qual-analysis','quant-analysis'],focus:'Agree what counts as an error, observe triggers and recovery, and retain task and user context.'},
{id:'abandonment',label:'Drop-off or abandoned tasks',question:'Where do people leave a task, and why?',objective:'Explain where and why tasks are abandoned',measurement:'Establish a comparable task or funnel baseline',methods:['existing-evidence','usability','interviews'],activities:['research-plan','protocol','run-sessions','organise-evidence','quant-analysis','combine-insights'],focus:'Locate the drop-off, check the denominator and task conditions, then investigate what happens at that point.'},
{id:'findability',label:'Hard to find or understand information',question:'What prevents people from finding or understanding what they need?',objective:'Identify barriers to finding and understanding information',measurement:'Measure task completion and effort for finding information',methods:['usability','observation','interviews'],activities:['frame-problem','research-plan','protocol','run-sessions','qual-analysis','combine-insights'],focus:'Use realistic information-seeking tasks and observe terminology, navigation, search reformulation and interpretation.'},
{id:'needs',label:'Unclear or unmet user needs',question:'Which needs and situations are not being addressed?',objective:'Understand unmet needs and current workarounds',measurement:'Define the need before choosing a measure of it',methods:['interviews','observation','existing-evidence'],activities:['frame-problem','research-plan','sampling','protocol','run-sessions','qual-analysis','combine-insights'],focus:'Start with recent situations, goals and workarounds; check which users and contexts the evidence covers.'},
{id:'accessibility',label:'Accessibility or inclusion barriers',question:'Who faces a barrier, in which situation, and with what consequence?',objective:'Understand barriers for the affected users and situations',measurement:'Define relevant tasks and coverage before comparing outcomes',methods:['expert-review','usability','observation'],activities:['frame-problem','sampling','protocol','run-sessions','qual-analysis','combine-insights'],focus:'Involve relevant access needs and assistive-technology use where appropriate. Combine specialist review with direct evidence; a general usability study does not establish accessibility compliance.'}
];
